mapper.insert:
/* apiReg.savApiRegInfo */

  SELECT SCOPE_IDENTITY()

INSERT INTO KOA_TB_API_SPC
(
   API_SPC_ID
  ,VER
  ,API_NM
  ,API_DESC
  ,AUT_ID
  ,SYS_ID
  ,VER_DESC
  ,RFRN_WSDL_URL
  ,RFRN_TMPLT_NO
  ,RFRN_API_SPC_NO
  ,HOST
  ,BAS_PATH
  ,YAML_FILE_PATH
  ,YAML_FILE_NM
  ,REG_STTUS_CD
  ,TMPLT_YN
  ,REG_APVR
  ,REG_DT
  ,REGR
  ,AMD_DT
  ,AMDR
  ,DEL_YN
  ,YAML_SBST
  ,SHOW_YN
  ,API_CLASS
  ,BSTGW_YN
  ,API_VERI_BASEURL
  ,PROJECT_NS
)
VALUES
(
  ( SELECT IDENT_CURRENT('KOA_TB_API_SPC') )
  ,#{ver}
  ,#{apiNm}
  ,#{apiDesc}
  ,#{autId}
  ,#{sysId}
  ,#{verDesc}
  ,#{rfrnWsdlUrl}
  ,#{rfrnTmpltNo}
  ,#{rfrnApiSpcNo}
  ,#{host}
  ,#{basPath}
  ,#{yamlFilePath}
  ,( SELECT IDENT_CURRENT('KOA_TB_API_SPC') )
  ,#{regSttusCd}
  ,#{tmpltYn}
  ,#{regApvr}
  ,NOW()
  ,#{regr}
  ,NOW()
  ,#{regr}
  ,'N'
  ,#{yamlSbst}
  ,'N'
  ,#{apiClass}
  ,#{bstgwYn}
  ,#{apiVeriBaseurl}
  ,#{projectNamespace}
)

mapper.update:
/* apiReg.updApiRegInfo */
UPDATE KOA_TB_API_SPC
SET
   HOST       = #{host}
  ,BAS_PATH   = #{basPath}
  ,API_NM     = #{apiNm}
  ,API_DESC   = #{apiDesc}
  ,AUT_ID     = #{autId}
  ,SYS_ID     = #{sysId}
  ,AMD_DT     = NOW()
  ,AMDR       = #{regr}
  ,YAML_SBST  = #{yamlSbst}
  ,API_CLASS  = #{apiClass}
  ,BSTGW_YN = #{bstgwYn}
  ,API_VERI_BASEURL = #{apiVeriBaseurl}

    ,PROJECT_NS = #{projectNamespace}

WHERE (API_SPC_NO = #{apiSpcNo})

/* apiReg.updApiYamlInfo */
UPDATE KOA_TB_API_SPC
SET
   AMD_DT    = NOW()
  ,AMDR      = #{regr}
  ,YAML_SBST = #{yamlSbst}
WHERE (API_SPC_NO = #{apiSpcNo})

mapper.select:
/* apiReg.selImportApiTotalList */ SELECT COUNT(*) FROM KOA_TB_API_SPC A WHERE (A.DEL_YN = 'N') AND (A.SHOW_YN = 'Y')
AND (A.REG_STTUS_CD = 'APIREG1030') AND ((A.TMPLT_YN != 'Y') OR (A.TMPLT_YN IS NULL))
AND (A.TMPLT_YN = 'Y')
AND A.AUT_ID IN
#{item}
AND ( (A.API_DESC LIKE CONCAT('%', #{schText}, '%')) OR ( A.SYS_ID IN ( SELECT SYS_ID FROM KOA_TB_API_SYSTEM B WHERE B.SYS_NM LIKE CONCAT('%', #{schText}, '%') ) ) OR (A.AMDR LIKE CONCAT('%', #{schText}, '%')) OR (A.API_NM LIKE CONCAT('%', #{schText}, '%')) )

mapper.insert:
/* apiReg.savApiCateInfo */

  SELECT SCOPE_IDENTITY()

INSERT INTO KOA_TB_API_CTGRY
(
   API_SPC_NO
  ,CTGRY_NM
  ,SORT_ODRG
  ,CTGRY_DESC
  ,DEL_YN
  ,REG_DT
  ,REGR
  ,AMD_DT
  ,AMDR
)
VALUES
(
  #{apiSpcNo}
  ,#{ctgryNm}
  ,(SELECT COALESCE(MAX(SORT_ODRG) + 1, 1 ) FROM KOA_TB_API_CTGRY  WHERE (API_SPC_NO = #{apiSpcNo}))
  ,#{ctgryDesc}
  ,'N'
  ,NOW()
  ,#{regr}
  ,NOW()
  ,#{regr}
)

mapper.update:
/* apiReg.updApiCateInfo */
UPDATE KOA_TB_API_CTGRY
SET
  CTGRY_NM    = #{ctgryNm}
  ,SORT_ODRG  = #{sortOdrg}
  ,CTGRY_DESC = #{ctgryDesc}
  ,AMD_DT     = NOW()
  ,AMDR       = #{regr}
WHERE (API_CTGRY_NO = #{apiCtgryNo})

/* apiReg.updApiCateSortOrder */
UPDATE KOA_TB_API_CTGRY
SET
  SORT_ODRG = #{sortOdrg}
  ,AMD_DT   = NOW()
  ,AMDR     = #{regr}
WHERE (API_CTGRY_NO = #{apiCtgryNo})

mapper.select:
/* apiReg.selApiInfoArsenal */ SELECT A.API_SPC_NO , API_SPC_ID , VER , API_NM , API_DESC , AUT_ID , A.SYS_ID , COALESCE(S.SYS_NM,'') AS SYS_ID_NM , COALESCE(A.VER_DESC,'') AS VER_DESC , RFRN_WSDL_URL , RFRN_TMPLT_NO , RFRN_API_SPC_NO , HOST , BAS_PATH , YAML_FILE_PATH , YAML_FILE_NM , REG_STTUS_CD , COALESCE(D.CD_NM,'') AS REG_STTUS_CD_NM , TMPLT_YN , A.REGR , A.AMD_DT , A.AMDR , A.DEL_YN , YAML_SBST , API_CLASS , BSTGW_YN , API_VERI_BASEURL
, N.PROJECT_NS AS PROJECT_NAMESPACE , N.PROJECT_NM AS PROJECT_NAME
FROM KOA_TB_API_SPC A LEFT OUTER JOIN KOA_TB_COMN_CD D ON (A.REG_STTUS_CD = D.COMN_CD AND D.GROUP_CD = 'APIREG1000') LEFT OUTER JOIN KOA_TB_API_SYSTEM S ON (S.SYS_ID = A.SYS_ID)
/* 네임스페이스 테이블 조인 추가 */ LEFT OUTER JOIN KOA_TB_API_SPC_NS N ON (A.API_SPC_NO=N.API_SPC_NO AND N.DEL_YN='N')
WHERE (A.API_SPC_NO = #{apiSpcNo})

mapper.insert:
/* apiReg.savApiPathInfo */

  SELECT SCOPE_IDENTITY()

INSERT INTO KOA_TB_API_DEF
(
   API_SPC_NO
  ,API_NM
  ,API_CTGRY_NO
  ,API_PATH
  ,METHOD_CD
  ,API_ID
  ,API_DESC
  ,REG_DT
  ,REGR
  ,AMD_DT
  ,AMDR
  ,SORT_ODRG
  ,USE_YN
  ,API_GUBUN
  ,API_HANDLER_CD
  ,ENDPNT_METHOD_CD
  ,ENDPNT_TB_URL
  ,ENDPNT_PRD_URL
  ,ENDPNT_TIMEOUT 
  ,ENDPNT_CLIENT_IP
  ,RESMAP_RES_CD_FIELD
  ,RESMAP_SUCC_VAL
  ,RESMAP_ERR_CD_FIELD
  ,RESMAP_ERR_MSG_FIELD
  ,HDP_API_OUT_FORMAT
  ,HDP_API_OUT_COMMON_PARAM
  ,HDP_API_ENDPOINT_ID
  ,HDP_REQ_API_NAME
  ,HDP_REQ_CONFIG_TO_BODY
  ,HDP_REQ_HEADER_TO_BODY
  ,HDP_REQ_MAPPING_TO_BODY
  ,HDP_REQ_URL_DECODE
  ,HDP_REQ_URL_ENCODE
  ,HDP_RES_MAPPING_TO_BODY
  ,HDP_RES_PROVIDE_PARAM
  ,HDP_RES_URL_ENCODE
  ,HDP_EXT_PROP
  ,HDP_HNDLROPTN_CONFIG
  ,API_VER
  ,API_VER_NO
  ,SANDBOX_YN
  ,GUIDE_GUBUN
  ,PROVIDER_SEQ
  ,BSTGW_TB_SYS_ID
  ,BSTGW_PRD_SYS_ID
)
VALUES
(
  #{apiSpcNo}
  ,#{apiNm}
  ,(
    SELECT API_CTGRY_NO
    FROM KOA_TB_API_CTGRY B 
    WHERE (B.API_SPC_NO = #{apiSpcNo})
      AND (UPPER(CTGRY_NM) = UPPER(#{apiCtgryNm}))
  )
  ,#{apiPath}
  ,(
    SELECT comn_cd FROM KOA_TB_COMN_CD 
    WHERE (group_cd = 'MTHTYP1000')
      AND (UPPER(cd_nm) LIKE CONCAT(UPPER(#{methodCd}), '%'))
  )
  ,#{apiId}
  ,#{apiDesc}
  ,NOW()
  ,#{regr}
  ,NOW()
  ,#{regr}
  ,#{sortOdrg}
  ,#{useYn}
  ,#{apiGubun}
  ,#{apiHandlerCd}
  ,#{endpntMethodCd}
  ,#{endpntTbUrl}
  ,#{endpntPrdUrl}
  ,#{endpntTimeout}
  ,#{endpntClientIp}
  ,#{resmapResCdField}
  ,#{resmapSuccVal}
  ,#{resmapErrCdField}
  ,#{resmapErrMsgField}
  ,#{hdpApiOutFormat}
  ,#{hdpApiOutCommonParam}
  ,#{hdpApiEndpointId}
  ,#{hdpReqApiName}
  ,#{hdpReqConfigToBody}
  ,#{hdpReqHeaderToBody}
  ,#{hdpReqMappingToBody}
  ,#{hdpReqUrlDecode}
  ,#{hdpReqUrlEncode}
  ,#{hdpResMappingToBody}
  ,#{hdpResProvideParam}
  ,#{hdpResUrlEncode}
  ,#{hdpExtProp}
  ,#{hdpHndlroptnConfig}
  ,#{apiVer}
  ,#{apiVerNo}
  ,#{sandboxYn}
  ,#{guideGubun}
  ,#{providerSeq}
  ,#{bstgwTbSysId}
  ,#{bstgwPrdSysId}
)

mapper.update:
/* apiReg.updApiPathInfo */
UPDATE KOA_TB_API_DEF
SET
  API_NM = #{apiNm}
  ,API_CTGRY_NO = (
    SELECT API_CTGRY_NO
    FROM KOA_TB_API_CTGRY B 
    WHERE (B.API_SPC_NO = #{apiSpcNo})
      AND (UPPER(CTGRY_NM) = UPPER(#{apiCtgryNm}))
  )
  ,API_PATH  = #{apiPath}
  ,METHOD_CD = (
    SELECT comn_cd
    FROM KOA_TB_COMN_CD 
    WHERE (group_cd = 'MTHTYP1000')
      AND (UPPER(cd_nm) LIKE CONCAT(UPPER(#{methodCd}), '%'))
  )
  ,API_ID    = #{apiId}
  ,API_DESC  = #{apiDesc}
  ,AMD_DT    = NOW()
  ,AMDR      = #{regr}
  ,USE_YN    = #{useYn}
  ,API_GUBUN = #{apiGubun}
  ,API_HANDLER_CD       = #{apiHandlerCd}
  ,ENDPNT_METHOD_CD     = #{endpntMethodCd}
  ,ENDPNT_TB_URL        = #{endpntTbUrl}
  ,ENDPNT_PRD_URL       = #{endpntPrdUrl}
  ,ENDPNT_TIMEOUT       = #{endpntTimeout}
  ,ENDPNT_CLIENT_IP     = #{endpntClientIp}
  ,RESMAP_RES_CD_FIELD  = #{resmapResCdField}
  ,RESMAP_SUCC_VAL      = #{resmapSuccVal}
  ,RESMAP_ERR_CD_FIELD  = #{resmapErrCdField}
  ,RESMAP_ERR_MSG_FIELD = #{resmapErrMsgField}
  ,HDP_API_OUT_FORMAT       = #{hdpApiOutFormat}
  ,HDP_API_OUT_COMMON_PARAM = #{hdpApiOutCommonParam}
  ,HDP_API_ENDPOINT_ID      = #{hdpApiEndpointId}
  ,HDP_REQ_API_NAME         = #{hdpReqApiName}
  ,HDP_REQ_CONFIG_TO_BODY   = #{hdpReqConfigToBody}
  ,HDP_REQ_HEADER_TO_BODY   = #{hdpReqHeaderToBody}
  ,HDP_REQ_MAPPING_TO_BODY  = #{hdpReqMappingToBody}
  ,HDP_REQ_URL_DECODE       = #{hdpReqUrlDecode}
  ,HDP_REQ_URL_ENCODE       = #{hdpReqUrlEncode}
  ,HDP_RES_MAPPING_TO_BODY  = #{hdpResMappingToBody}
  ,HDP_RES_PROVIDE_PARAM    = #{hdpResProvideParam}
  ,HDP_RES_URL_ENCODE       = #{hdpResUrlEncode}
  ,HDP_EXT_PROP             = #{hdpExtProp}
  ,HDP_HNDLROPTN_CONFIG     = #{hdpHndlroptnConfig}
  ,API_VER = #{apiVer}
  ,SANDBOX_YN = #{sandboxYn}
  ,GUIDE_GUBUN = #{guideGubun}
  ,PROVIDER_SEQ = #{providerSeq}
  ,BSTGW_TB_SYS_ID = #{bstgwTbSysId}
  ,BSTGW_PRD_SYS_ID = #{bstgwPrdSysId}
WHERE (API_NO = #{apiNo})

mapper.insert:
/* apiReg.savApiImpactInfo */
INSERT INTO KOA_TB_API_IMPACT
(
    API_NO

  , IMPACT


  , API_USER


  , REPROCESSABLE_YN


  , INTEGRATION_TYPE


  , API_METHOD


  , ENABLER_INFO


  , COMMENTS

  , REG_DT

  , REGR

  , AMD_DT

  , AMDR

)
VALUES
(
    #{apiNo}

  , #{impact}


  , #{apiUser}


  , #{reprocessableYn}


  , #{intergrationType}


  , #{apiMethod}


  , #{enablerInfo}


  , #{comments}

  , NOW()

  , #{regr}

  , NOW()

  , #{regr}

)

mapper.update:
/* apiReg.updApiImpactInfo */
UPDATE 
	KOA_TB_API_IMPACT
SET
	  AMD_DT    		= NOW()

  	, AMDR      		= #{regr}


	, IMPACT 			= #{impact}


	, API_USER 			= #{apiUser}


	, REPROCESSABLE_YN 	= #{reprocessableYn}


	, INTEGRATION_TYPE 	= #{intergrationType}


	, API_METHOD 		= #{apiMethod}


	, ENABLER_INFO 		= #{enablerInfo}


	, COMMENTS 			= #{comments}

WHERE 
	API_NO = #{apiNo}

mapper.delete:
/* apiReg.delApiSpcPathParam */
DELETE KOA_TB_API_PARAM
WHERE (API_NO = ( SELECT API_NO FROM KOA_TB_API_DEF  WHERE (API_SPC_NO  = #{apiSpcNo}) ))

/* apiReg.delApiAllPathParam */ DELETE KOA_TB_API_PARAM WHERE API_NO IN ( SELECT API_NO FROM KOA_TB_API_DEF WHERE (1 = 1)
AND (API_PATH = #{apiPath})
AND (API_SPC_NO = #{apiSpcNo}) )

/* apiReg.delApiSpcImpact */
DELETE KOA_TB_API_IMPACT
WHERE API_NO IN ( SELECT API_NO FROM KOA_TB_API_DEF  WHERE (API_SPC_NO  = #{apiSpcNo}) )

/* apiReg.delApiAllImpact */
DELETE KOA_TB_API_IMPACT
WHERE API_NO IN (
  SELECT API_NO
  FROM KOA_TB_API_DEF 
  WHERE API_SPC_NO  = #{apiSpcNo}

  AND API_PATH  = #{apiPath}

  )

