mapper.update:
/* apiReg.updApiHisInfo */
INSERT INTO KOA_TB_API_MGT_HST
(
   API_SPC_NO
  ,API_STTUS_CD
  ,MEMO
  ,REG_DT
  ,REGR
  ,DIRECTION
)
VALUES
(
   #{apiSpcNo}
  ,#{apiSttusCd}
  ,#{memo}
  ,NOW()
  ,#{regr}
  ,#{delr}
)

/* apiReg.updApiRegRestBasic */
UPDATE KOA_TB_API_SPC
SET
   HOST         = #{host}
  ,BAS_PATH     = #{basPath}
  ,API_NM       = #{apiNm}
  ,API_DESC     = #{apiDesc}
  ,REG_STTUS_CD = #{regSttusCd}
  ,AMD_DT       = NOW()
  ,AMDR         = #{regr}
  ,YAML_SBST    = #{yamlSbst}

    ,PROJECT_NS = #{projectNamespace}

WHERE (API_SPC_NO = #{apiSpcNo})

/* apiReg.insApiParamContType */
INSERT INTO KOA_TB_API_PARAM_CONT_TYPE
(
  PARAM_NO
  ,CONT_TYPE_CD
)
VALUES(
  #{paramNo}
  ,(
    SELECT comn_cd FROM KOA_TB_COMN_CD 
    WHERE (group_cd = 'CNTTYP1000')
      AND (UPPER(cd_nm) = UPPER(#{contTypeCd}))
  )
)

mapper.select:
/* apiReg.selApiSpcHistory */ SELECT A.HST_NO , A.MEMO , TO_CHAR(A.REG_DT, 'YYYY-MM-DD HH24:MI:SS') AS REG_DT , A.REGR
, CASE WHEN A.DIRECTION = 'A' THEN 'STUDIO <- ARSENAL' ELSE 'STUDIO -> ARSENAL' END AS DIRECTION
, B.CD_NM FROM KOA_TB_API_MGT_HST A LEFT OUTER JOIN KOA_TB_COMN_CD B ON (A.API_STTUS_CD=B.COMN_CD AND B.USE_YN='Y') WHERE A.API_SPC_NO=#{apiSpcNo}
AND A.DIRECTION IS NOT NULL
ORDER BY A.REG_DT DESC

/* apiReg.selApiSpcInfoByProjectNsWithNm */
SELECT A.API_SPC_NO, A.YAML_FILE_PATH, A.YAML_FILE_NM
  FROM KOA_TB_API_SPC A 
 WHERE A.DEL_YN = 'N'
   AND A.PROJECT_NS = #{projectNS}
   AND A.API_NM   = #{projectNM}
 LIMIT 1

mapper.insert:
/* apiReg.savArsenalApiNS */
INSERT INTO KOA_TB_API_SPC_NS
(
    API_SPC_NO
  , PROJECT_NS
  , PROJECT_NM
  , REG_DT
  , REGR
  , DEL_YN
)
VALUES(
    #{apiSpcNo}
  , #{projectNS}
  , #{projectNM}
  , NOW()
  , #{regr}
  , 'N'
)

mapper.update:
/* apiReg.updArsenalApiNS */
UPDATE KOA_TB_API_SPC_NS
SET
    EDIT_DT    = NOW()
  , EDITR      = #{editr}

  , PROJECT_NS = #{projectNS}


  , PROJECT_NM = #{projectNM}


  , DEL_YN     = #{delYn}

WHERE (API_SPC_NO = #{apiSpcNo})

mapper.select:
 /* apiReg.selApiSpcAuthCheck */
 SELECT COUNT(SEQ) AS CNT
 FROM KOA_TB_AUT_SPC A 
WHERE A.SPC_NO = #{apiSpcNo}
    AND A.MBR_ID = #{regr}

 /* apiReg.selMbrAuthCheck */
 SELECT COUNT(A.MBR_ID) AS CNT
   FROM KOA_TB_MBR A 
WHERE A.USE_YN = 'Y'
  AND A.IPADDRESS IS NOT NULL
    AND A.MBR_ID = #{regr}

SELECT A.AUT_ID
  FROM KOA_TB_AUT A 
 WHERE A.USE_YN = 'Y'
   AND A.SYS_ID = #{sysId}
   AND A.AUT_NM = #{autNm}

